executable_reference.program:
"""Executable SPECIFICATION oracle. No planner imports, effects or E1 operations.
Trusted profile is an independent admitted contract input, never a caller flag.
"""
import hashlib,json

def canonical(x):
    if isinstance(x,float): raise ValueError('float forbidden')
    if isinstance(x,dict):
        if any(type(k) is not str for k in x): raise ValueError('key type')
        for v in x.values(): canonical(v)
    if isinstance(x,list):
        for v in x: canonical(v)
    if not isinstance(x,(dict,list,str,int,bool,type(None))): raise ValueError('JSON type')
    return json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def parse(raw):
    def pairs(items):
        d={}
        for k,v in items:
            if k in d:raise ValueError('duplicate key')
            d[k]=v
        return d
    x=json.loads(raw,object_pairs_hook=pairs,parse_constant=lambda v:(_ for _ in ()).throw(ValueError('nonfinite')))
    canonical(x)
    return x
def digest(x):return hashlib.sha256(canonical(x)).hexdigest()
def equal(a,b):return canonical(a)==canonical(b)
def fields(x,keys):return type(x) is dict and set(x)==set(keys.split())
def identity(kind,name):return dict(kind=kind,namespace='SYNTHETIC/'+name,digest=hashlib.sha256(name.encode()).hexdigest())
KINDS={'CONTENT_IDENTITY','AUTHORITY_IDENTITY','INSTANCE_IDENTITY','RELEASE_IDENTITY','CANONICAL_OBJECT_IDENTITY','WORKAUTHORIZATION_ID','BINDING_DIGEST'}
def typed_id(x):
    return fields(x,'kind namespace digest') and x['kind'] in KINDS and type(x['namespace']) is str and bool(x['namespace']) and type(x['digest']) is str and len(x['digest'])==64 and all(c in '0123456789abcdef' for c in x['digest'])

def evaluate(profile,state):
    # Admitted profile binds base contracts and producer competence independently.
    # Return false/PLAN_DEFECT on malformed input, never substitute a default.
    try:return _evaluate(profile,state)
    except (KeyError,TypeError,ValueError,RecursionError):
        return {'accepted':False,'control':'PLAN_DEFECT','resume_allowed':False,'error':'MALFORMED_OR_UNBOUND_INPUT'}

def _evaluate(profile,s):
    if not fields(s,'schema base records sources invalidated proofs decisions receipts overlay cached_control') or s['schema']!='C06A2-ORACLE-STATE-1':raise ValueError('state schema')
    b=s['base']; o=s['overlay']; ctx=b['context']
    if digest(b)!=profile['base_pin'] or profile['mode']!='SYNTHETIC_QUALIFICATION_ONLY':raise ValueError('profile/base')
    if not fields(b,'context actions proof_contracts decision_contracts receipt_contracts goals boundaries global_defect local_defects resume_policy'):raise ValueError('base schema')
    if not fields(ctx,'graph plan policy policy_version scope lineage runtime G4 generation profile invocation dispatch context binding release'):raise ValueError('context')
    for key,kind in [('graph','CONTENT_IDENTITY'),('plan','CONTENT_IDENTITY'),('policy','CONTENT_IDENTITY'),('runtime','CONTENT_IDENTITY'),('G4','INSTANCE_IDENTITY'),('profile','CANONICAL_OBJECT_IDENTITY'),('invocation','INSTANCE_IDENTITY'),('dispatch','CANONICAL_OBJECT_IDENTITY'),('context','CANONICAL_OBJECT_IDENTITY'),('binding','BINDING_DIGEST'),('release','RELEASE_IDENTITY')]:
        if not typed_id(ctx[key]) or ctx[key]['kind']!=kind:raise ValueError('context domain')
    if type(ctx['generation']) not in [int,str] or type(ctx['scope']) is not str or type(ctx['lineage']) is not str:raise ValueError('context values')
    if not fields(o,'schema identity base_graph base_plan policy policy_version context ledger current_actions imported_support operational_digest admission_pin') or o['schema']!='C06A2-OVERLAY-1':raise ValueError('overlay schema')
    operational={k:s[k] for k in ['records','invalidated','proofs','decisions','receipts']}
    if o['operational_digest']!=digest(operational) or o['admission_pin']!=digest(profile):raise ValueError('operational/admission binding')
    if s['invalidated']!=profile['invalidation_admission']:raise ValueError('unadmitted invalidation change')
    body={k:v for k,v in o.items() if k!='identity'}
    if not typed_id(o['identity']) or o['identity']['kind']!='CONTENT_IDENTITY' or o['identity']['digest']!=digest(body):raise ValueError('overlay identity')
    for key,ck in [('base_graph','graph'),('base_plan','plan'),('policy','policy'),('policy_version','policy_version'),('context',None)]:
        if not equal(o[key],ctx if ck is None else ctx[ck]):raise ValueError('overlay binding')
    if b['resume_policy'] not in ['EXTERNAL_ONLY','ADMITTED_DECISION_OR_EXTERNAL']:raise ValueError('resume policy')
    if len(set(s['invalidated']))!=len(s['invalidated']) or any(r not in s['records'] for r in s['invalidated']):raise ValueError('invalidation reference')
    for rid,r in s['records'].items():
        if not fields(r,'kind role owner context source_scope dependencies claims provenance') or r['kind'] not in KINDS:raise ValueError('record schema')
        if not fields(r['provenance'],'path selector raw_identity extraction') or not r['provenance']['path'] or not r['provenance']['selector'] or not r['provenance']['extraction']:raise ValueError('provenance')
        if not typed_id(r['provenance']['raw_identity']) or r['provenance']['raw_identity']['kind']!='CONTENT_IDENTITY':raise ValueError('raw source domain')
        if any(d not in s['records'] for d in r['dependencies']) or len(set(r['dependencies']))!=len(r['dependencies']):raise ValueError('record dependency')
        path=r['provenance']['path']; raw=s['sources'][path].encode('utf-8')
        if hashlib.sha256(raw).hexdigest()!=r['provenance']['raw_identity']['digest'] or profile['source_pins'].get(path)!=r['provenance']['raw_identity']:raise ValueError('source bytes')
        selected=parse(raw)
        for key in r['provenance']['selector'].split('/')[1:]:selected=selected[key]
        if not equal(selected,r['claims']):raise ValueError('provenance claim projection')
        # Every referenced source byte pin must be verified; self hashes aren't trust.
        if profile['record_pins'].get(rid)!=digest(r):raise ValueError('source pin')
        if r['role'] not in profile['producer_roles'].get(r['owner'],[]):raise ValueError('producer competence')
    def current(rid,role=None,kind=None,seen=()):
        if rid not in s['records'] or rid in seen or rid in s['invalidated']:return False
        r=s['records'][rid]
        admission=profile['currentness_admissions'].get(rid)
        attested=admission=={'record_digest':digest(r),'context_digest':digest(ctx),'rule':'PINNED_QUALIFICATION_SNAPSHOT'}
        return (attested and equal(r['context'],ctx) and (role is None or r['role']==role) and (kind is None or r['kind']==kind)
                and all(current(d,seen=seen+(rid,)) for d in r['dependencies']))
    def claim(rid,role,expected,kind='CONTENT_IDENTITY'):
        return current(rid,role,kind) and all(k in s['records'][rid]['claims'] and equal(s['records'][rid]['claims'][k],v) for k,v in expected.items())
    global_invalid=False
    if b['global_defect'] is not None:
        if not claim(b['global_defect'],'PLANNER_DEFECT',{'scope':'ALL'}):raise ValueError('unproven global defect')
        global_invalid=True
    for aid,rid in b['local_defects'].items():
        if aid not in b['actions'] or not claim(rid,'PLANNER_DEFECT',{'scope':aid}):raise ValueError('unproven local defect')
    decisions={}
    stage_set={'SEMANTIC_GAP_IDENTIFIED','DECISION_INPUTS_REQUIRED','DECISION_INPUT_ACQUISITION','DECISION_DOSSIER_READY','DECISION_READY','DECISION_RECORDED','DOWNSTREAM_REEVALUATION'}
    for did,c in b['decision_contracts'].items():
        if not fields(c,'question options scope lineage routes exclusions facts external_facts attestation authority_type permission applicability_required applicability applicability_rule gap authority_ref authority_identity') or type(c['applicability_required']) is not bool:raise ValueError('decision contract schema')
        d=s['decisions'][did]
        if not fields(d,'historical_stage trigger_result dossier option authority') or d['historical_stage'] not in stage_set or d['trigger_result'] not in ['PASS','BLOCKED','AUTHORITY_REQUIRED']:raise ValueError('decision schema')
        fact_complete=all(claim(r,'DECISION_FACT',{'decision':did,'predicate':p}) for p,r in c['facts'].items())
        external_missing=any(not claim(c['facts'][p],'DECISION_FACT',{'decision':did,'predicate':p}) for p in c['external_facts'])
        dos_ok=claim(d['dossier'],'DOSSIER',{'decision':did,'question':c['question'],'options':c['options'],'scope':c['scope'],'lineage':c['lineage'],'routes':c['routes'],'exclusions':c['exclusions'],'required_facts':sorted(c['facts'])})
        dossier_ready=dos_ok and fact_complete
        att=c['attestation']
        ready=dossier_ready and claim(att,'READINESS_ATTESTATION',{'decision':did,'dossier':d['dossier'],'dossier_digest':profile['record_pins'].get(d['dossier']),'checks':list(range(1,10))})
        if ready: ready=s['records'][att]['owner']!=s['records'][d['dossier']]['owner']
        recorded=claim(d['authority'],'ARCHITECT_DECISION',{'decision':did,'dossier':d['dossier'],'dossier_digest':profile['record_pins'].get(d['dossier']),'option':d['option'],'scope':c['scope'],'lineage':c['lineage'],'routes':c['routes'],'exclusions':c['exclusions'],'authority_type':c['authority_type']},'AUTHORITY_IDENTITY')
        recorded=recorded and dos_ok and d['option'] in c['options'] and d['authority']==c['authority_ref']
        if recorded:
            ai=s['records'][d['authority']]['claims']['authority_identity']
            ab={k:v for k,v in s['records'][d['authority']]['claims'].items() if k!='authority_identity'}
            recorded=typed_id(ai) and ai['kind']=='AUTHORITY_IDENTITY' and equal(ai,c['authority_identity']) and ai['digest']==digest(ab)
        if recorded:recorded=s['records'][d['authority']]['source_scope']==c['scope']
        usable=False
        if recorded:
            a=s['records'][d['authority']]['claims']
            if a['outcome'] not in ['APPROVE','REJECT','DEFER'] or type(a['single_use']) is not bool or a['use_state'] not in ['UNCONSUMED','CONSUMED','UNKNOWN']:raise ValueError('authority state')
            usable=(a['outcome']=='APPROVE' and (not a['single_use'] or a['use_state']=='UNCONSUMED') and equal(a['permission'],c['permission']))
            if c['applicability_required']:
                usable=usable and claim(c['applicability'],'APPLICABILITY',{'authority':d['authority'],'target_scope':c['scope'],'lineage':c['lineage'],'rule':c['applicability_rule']}) and current(c['applicability_rule'],'GOVERNING_RULE')
        gap_ok=claim(c['gap'],'GAP',{'decision':did})
        if recorded: derived='DECISION_RECORDED'
        elif ready: derived='DECISION_READY'
        elif dossier_ready: derived='DECISION_DOSSIER_READY'
        elif gap_ok: derived='DECISION_INPUTS_REQUIRED'
        else: derived='UNESTABLISHED'
        decisions[did]={'derived_stage':derived,'dossier_ready':dossier_ready,'decision_ready':ready and not recorded,'recorded':recorded,'grant_usable':usable,'fact_blocked':external_missing,'authority_required':d['trigger_result']=='AUTHORITY_REQUIRED' and gap_ok,'gap_established':gap_ok,'historical_stage':d['historical_stage']}
    if set(s['decisions'])!=set(b['decision_contracts']):raise ValueError('decision inventory')
    memo={}
    def proof(target,seen=()):
        if target in memo:return memo[target]
        if target in seen:return False
        c=b['proof_contracts'][target];p=s['proofs'].get(target)
        if p is None:return False
        if not fields(p,'identity target contract value supports') or not typed_id(p['identity']) or p['identity']['kind']!='CONTENT_IDENTITY' or p['identity']['namespace']!='proof-v1':return False
        payload={k:v for k,v in p.items() if k!='identity'}
        if p['identity']['digest']!=digest(payload) or p['target']!=target or p['contract']!=digest(c):return False
        if sorted(p['supports'])!=sorted(q['record'] for q in c['requirements']):return False
        okay=all(claim(q['record'],q['role'],q['claims'],q['kind']) for q in c['requirements'])
        okay=okay and all(proof(dep,seen+(target,)) for dep in c['dependencies'])
        if c['authority_decision'] is not None:okay=okay and decisions[c['authority_decision']]['grant_usable']
        if c['target_kind']=='SLOT':
            okay=okay and equal(p['value'],c['value']) and (not c['identity_value'] or (typed_id(p['value']) and p['value']['kind']==c['value_kind']))
        elif c['target_kind']=='ROOT':okay=okay and p['value'] is None
        else:raise ValueError('proof target kind')
        memo[target]=bool(okay);return bool(okay)
    for target,c in b['proof_contracts'].items():
        if not fields(c,'target_kind requirements dependencies authority_decision value identity_value value_kind') or type(c['identity_value']) is not bool:raise ValueError('proof contract schema')
        if not c['requirements'] or any(dep not in b['proof_contracts'] for dep in c['dependencies']):raise ValueError('proof contract')
        proof(target)
    if any(k not in b['proof_contracts'] for k in s['proofs']):raise ValueError('proof target reference')
    # C03 accepted reentry evidence: native causal events OR imported attestation.
    ledger=o['ledger']
    if not fields(ledger,'kind base head events') or ledger['kind'] not in ['NATIVE','IMPORTED']:raise ValueError('ledger kind')
    if not equal(ledger['base'],ctx['graph']):raise ValueError('ledger base')
    parent=digest(ledger['base']);native_reentry=set();native_decision_reentry=set();validation_events=set()
    expected_actions={aid:a['initial_state'] for aid,a in b['actions'].items()}
    for seq,event in enumerate(ledger['events']):
        if not fields(event,'sequence parent kind receipt action context identity') or event['sequence']!=seq or event['parent']!=parent or not equal(event['context'],ctx):raise ValueError('ledger chain')
        ebody={k:v for k,v in event.items() if k!='identity'}
        if event['identity']!=digest(ebody):raise ValueError('event identity')
        if event['kind'] in ['RECEIPT_VALIDATED','REENTRY'] and (event['receipt'] not in b['receipt_contracts'] or event['action'] not in b['receipt_contracts'][event['receipt']]['route']):raise ValueError('event route reference')
        if event['kind']=='RECEIPT_VALIDATED':validation_events.add(event['receipt'])
        elif event['kind']=='REENTRY':
            if event['receipt'] not in validation_events or event['action'] not in b['actions']:raise ValueError('unsupported reentry event')
            native_reentry.add((event['receipt'],event['action']));expected_actions[event['action']]='PENDING'
        elif event['kind']=='DECISION_REENTRY':
            if event['receipt'] not in b['decision_contracts'] or event['action'] not in b['decision_contracts'][event['receipt']]['routes']:raise ValueError('decision reentry route')
            native_decision_reentry.add((event['receipt'],event['action']));expected_actions[event['action']]='PENDING'
        else:raise ValueError('unsupported event')
        parent=event['identity']
    if ledger['head']!=parent:raise ValueError('ledger head')
    if ledger['kind']=='NATIVE':
        if not equal(expected_actions,o['current_actions']):raise ValueError('overlay not replay-derived')
    else:
        if ledger['events'] or not claim(o['imported_support'],'IMPORTED_OVERLAY',{'ledger_head':ledger['head'],'action_states':o['current_actions'],'base_graph':ctx['graph'],'policy':ctx['policy']}):raise ValueError('imported overlay source')
    if set(o['current_actions'])!=set(b['actions']) or any(v not in ['PENDING','COMPLETED','BLOCKED','WAITING'] for v in o['current_actions'].values()):raise ValueError('action states')
    receipts={}
    for rid,c in b['receipt_contracts'].items():
        if not fields(c,'request route scope lineage producer waiting_declared obligations') or type(c['waiting_declared']) is not bool or not c['route'] or any(a not in b['actions'] for a in c['route']):raise ValueError('receipt contract schema/route')
        r=s['receipts'][rid]
        if not fields(r,'stage evidence obligation_records reentry_attestation') or r['stage'] not in ['EVIDENCE_REQUEST_READY','WAITING_FOR_EXTERNAL_EVIDENCE','EVIDENCE_RECEIVED','EVIDENCE_VALIDATED','DEPENDENT_ACTION_REENTRY']:raise ValueError('receipt stage')
        present=r['evidence'] in s['records']
        valid=present and claim(r['evidence'],'EXTERNAL_EVIDENCE',{'request':c['request'],'receipt_contract':digest(c),'route':c['route'],'scope':c['scope'],'lineage':c['lineage']})
        if present:valid=valid and s['records'][r['evidence']]['owner']==c['producer'] and s['records'][r['evidence']]['source_scope']==c['scope']
        valid=valid and sorted(r['obligation_records'])==sorted(c['obligations'])
        for name,q in c['obligations'].items():
            valid=valid and current(q['rule'],'GOVERNING_RULE') and claim(r['obligation_records'].get(name),'RECEIPT_PROOF',{'request':c['request'],'obligation':name,'rule':q['rule'],'evidence':r['evidence'],'value':q['value']})
        imported=claim(r['reentry_attestation'],'REENTRY_ATTESTATION',{'receipt':rid,'request':c['request'],'route':c['route'],'evidence':r['evidence'],'ledger_head':ledger['head'],'policy':ctx['policy']}) if r['reentry_attestation'] else False
        reentry=valid and (all((rid,a) in native_reentry for a in c['route']) or (ledger['kind']=='IMPORTED' and imported))
        derived=('DEPENDENT_ACTION_REENTRY' if reentry else 'EVIDENCE_VALIDATED' if valid else 'EVIDENCE_RECEIVED' if present else 'WAITING_FOR_EXTERNAL_EVIDENCE' if c['waiting_declared'] else 'EVIDENCE_REQUEST_READY')
        receipts[rid]={'received':present,'validated':bool(valid),'reentry':bool(reentry),'derived_stage':derived,'stage_currently_supported':r['stage']==derived}
    if set(s['receipts'])!=set(b['receipt_contracts']):raise ValueError('receipt inventory')
    machine=[];human=[]
    for aid,a in b['actions'].items():
        if not fields(a,'executor effect initial_state proofs knowledge completed_prerequisites execution_scope route decision authority_decision'):raise ValueError('action contract schema')
        if a['executor'] not in ['MACHINE','HUMAN'] or a['effect']!='NON_EFFECTING':raise ValueError('unsupported action scope')
        valid=o['current_actions'][aid]=='PENDING' and all(proof(x) for x in a['proofs']) and all(claim(x['record'],x['role'],x['claims'],x['kind']) for x in a['knowledge']) and aid not in b['local_defects']
        valid=valid and all(claim(r,'ACTION_COMPLETION',{'action':dep}) for dep,r in a['completed_prerequisites'].items())
        valid=valid and claim(a['execution_scope'],'EXECUTION_SCOPE',{'action':aid,'effect':'NON_EFFECTING'})
        if a['route'] is not None:valid=valid and receipts[a['route']]['reentry'] and aid in b['receipt_contracts'][a['route']]['route']
        if a['authority_decision'] is not None:valid=valid and decisions[a['authority_decision']]['grant_usable']
        if a['executor']=='HUMAN':valid=valid and decisions[a['decision']]['decision_ready']
        if valid:(machine if a['executor']=='MACHINE' else human).append(aid)
    machine.sort();human.sort()
    if not b['goals'] or any(not fields(g,'id target frontier failure_record') for g in b['goals']):raise ValueError('goal contract')
    unresolved=[g for g in b['goals'] if not proof(g['target'])]
    frontier=set();missing_route=False;terminal_failure=False
    for g in unresolved:
        failure_ok=g['failure_record'] is not None and claim(g['failure_record'],'UNRECOVERABLE',{'goal':g['id'],'no_recovery':True})
        terminal_failure=terminal_failure or failure_ok
        if not g['frontier'] and not failure_ok:missing_route=True
        for q in g['frontier']:
            if q not in b['boundaries']:raise ValueError('frontier reference')
            frontier.add(q)
    kinds=set()
    for q in frontier:
        boundary=b['boundaries'][q]
        if not fields(boundary,'kind receipt'):raise ValueError('boundary contract')
        if boundary['kind']=='EXTERNAL_EVIDENCE':
            r=boundary['receipt']
            if r not in receipts or not b['receipt_contracts'][r]['obligations']:raise ValueError('external wait lacks contract')
            if receipts[r]['validated']:missing_route=True  # no longer evidence-waiting; missing further control path
        kinds.add(boundary['kind'])
    if not kinds.issubset({'EXTERNAL_EVIDENCE','EXTERNAL_SOURCE','AUTHORITY','IMPLEMENTATION','PLAN_DEFECT'}):raise ValueError('boundary type')
    if global_invalid:control='PLAN_DEFECT';machine=[];human=[]
    elif machine:control='RUNNABLE'
    elif human:control='HUMAN_HANDOFF'
    elif missing_route or 'PLAN_DEFECT' in kinds:control='PLAN_DEFECT'
    elif not unresolved:control='TERMINAL_SUCCESS'
    elif terminal_failure:control='TERMINAL_FAILURE'
    elif kinds=={'EXTERNAL_EVIDENCE'}:control='EXTERNAL_WAIT'
    else:control='MIXED_WAIT'
    # Existing C03 relationship, not a new permission. No selection/execution here.
    resume=not global_invalid and any(v['reentry'] and any(a in machine+human for a in b['receipt_contracts'][r]['route']) for r,v in receipts.items())
    if b['resume_policy']=='ADMITTED_DECISION_OR_EXTERNAL' and not global_invalid:
        resume=resume or any(decisions[d]['grant_usable'] and a in machine+human for d,a in native_decision_reentry)
    return {'accepted':s['cached_control'] is None or s['cached_control']==control,'control':control,'machine':machine,'human':human,'proofs':{t:proof(t) for t in sorted(b['proof_contracts'])},'decisions':decisions,'receipts':receipts,'frontier':sorted(frontier),'resume_allowed':resume}


def accepted(profile,state,query):
    """Family acceptance, separate from historical preservation and derivation."""
    out=evaluate(profile,state)
    if not out.get('accepted',False):return False
    try:
        family=query['family']
        if family=='decision_state':
            d=out['decisions'][query['id']];want=query['state']
            if want=='AUTHORITY_REQUIRED':return d['authority_required']
            if want=='FACT_BLOCKED':return d['fact_blocked']
            return d['derived_stage']==want
        if family=='authority_use':return out['decisions'][query['id']]['grant_usable']
        if family=='proof':return out['proofs'][query['id']]
        if family=='receipt_state':return out['receipts'][query['id']]['derived_stage']==query['state']
        if family=='control':return out['control']==query['state']
        if family=='resume':return out['resume_allowed']
        if family=='overlay':return True
    except (KeyError,TypeError):return False
    return False
